	let y; let mo; let d;
	if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; } else {
		m = raw.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);
		if (!m) { return null; }
		d = +m[1]; mo = +m[2]; y = +m[3];
		if (y < 100) { y += y >= 70 ? 1900 : 2000; }
	}
	if (mo < 1 || mo > 12 || d < 1 || d > 31) { return null; }
	const t = Date.UTC(y, mo - 1, d);
	const back = new Date(t);
	if (back.getUTCDate() !== d) { return null; }
